// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title UAVConsistencyLedger
 * @notice Permissioned smart contract for detecting Byzantine equivocation in
 *         distributed UAV localization / ADMM iterations.
 *
 * Core idea:
 * - Each UAV is allowed to finalize only ONE commitment for a given
 *   (sessionId, iteration, uavId).
 * - If the same UAV later submits a different commitment for the same round,
 *   the contract records an equivocation/conflict event.
 * - A receiving UAV can also submit the commitment it actually received from a
 *   sender. If the received commitment differs from the sender's finalized
 *   commitment, the contract records an inconsistent-packet observation.
 *
 * The contract stores hashes/commitments instead of large floating-point state
 * vectors. In the paper notation, the off-chain packet may be
 * p_i^k = (i, sid, k, m_i^k, r_i^k, c_i^k), where
 * c_i^k = H(i || sid || k || m_i^k || r_i^k).
 * This contract stores c_i^k and payload/state digests so anyone can verify
 * that a UAV did not finalize multiple inconsistent values in the same round.
 */
contract UAVConsistencyLedger {
    // ---------------------------------------------------------------------
    // Ownership and permissioning
    // ---------------------------------------------------------------------
    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyValidator() {
        require(validators[msg.sender], "Only validator");
        _;
    }

    modifier onlyRegisteredUAV() {
        require(uavsByAddress[msg.sender].registered, "UAV not registered");
        _;
    }

    constructor() {
        owner = msg.sender;
        validators[msg.sender] = true;
        emit ValidatorUpdated(msg.sender, true);
    }

    // ---------------------------------------------------------------------
    // UAV and validator registry
    // ---------------------------------------------------------------------
    struct UAVInfo {
        bool registered;
        uint256 uavId;
        string metadata;
        uint256 registeredAt;
    }

    mapping(address => UAVInfo) public uavsByAddress;
    mapping(uint256 => address) public addressOfUav;
    mapping(address => bool) public validators;

    event UAVRegistered(
        uint256 indexed uavId,
        address indexed uavAddress,
        string metadata,
        uint256 timestamp
    );

    event ValidatorUpdated(
        address indexed validator,
        bool authorized
    );

    function registerUAV(
        uint256 uavId,
        address uavAddress,
        string calldata metadata
    ) external onlyOwner {
        require(uavAddress != address(0), "Invalid UAV address");
        require(!uavsByAddress[uavAddress].registered, "Address already registered");
        require(addressOfUav[uavId] == address(0), "UAV id already registered");

        uavsByAddress[uavAddress] = UAVInfo({
            registered: true,
            uavId: uavId,
            metadata: metadata,
            registeredAt: block.timestamp
        });

        addressOfUav[uavId] = uavAddress;

        emit UAVRegistered(uavId, uavAddress, metadata, block.timestamp);
    }

    function setValidator(address validator, bool authorized) external onlyOwner {
        require(validator != address(0), "Invalid validator address");
        validators[validator] = authorized;
        emit ValidatorUpdated(validator, authorized);
    }

    // ---------------------------------------------------------------------
    // State commitment and inconsistency records
    // ---------------------------------------------------------------------
    struct StateRecord {
        bool exists;
        uint256 uavId;
        address sender;
        bytes32 sessionId;
        uint256 iteration;
        bytes32 commitment;      // c_i^k = H(i || sid || k || payload || nonce)
        bytes32 payloadDigest;   // H(payload), useful for off-chain audit
        bytes32 stateDigest;     // H(x_i^k) or H(serialized state vector)
        int256 xScaled;          // optional readable x coordinate, scaled off-chain
        int256 yScaled;          // optional readable y coordinate, scaled off-chain
        uint256 timestamp;
    }

    struct ObservationRecord {
        bool exists;
        uint256 receiverId;
        address receiver;
        bytes32 observedCommitment;
        bytes32 observedPayloadDigest;
        uint256 timestamp;
        bool matchesFinalizedCommitment;
    }

    // sessionId => iteration => uavId => finalized state record
    mapping(bytes32 => mapping(uint256 => mapping(uint256 => StateRecord))) private stateRecords;

    // sessionId => iteration => uavId => conflicting commitments reported/submitted
    mapping(bytes32 => mapping(uint256 => mapping(uint256 => bytes32[]))) private conflictingCommitments;

    // sessionId => iteration => senderUavId => receiverUavId => observation
    mapping(bytes32 => mapping(uint256 => mapping(uint256 => mapping(uint256 => ObservationRecord)))) private observations;

    event StateCommitted(
        bytes32 indexed sessionId,
        uint256 indexed iteration,
        uint256 indexed uavId,
        address sender,
        bytes32 commitment,
        bytes32 payloadDigest,
        bytes32 stateDigest,
        int256 xScaled,
        int256 yScaled,
        uint256 timestamp
    );

    event DuplicateConsistentCommitment(
        bytes32 indexed sessionId,
        uint256 indexed iteration,
        uint256 indexed uavId,
        bytes32 commitment,
        uint256 timestamp
    );

    event EquivocationDetected(
        bytes32 indexed sessionId,
        uint256 indexed iteration,
        uint256 indexed uavId,
        address sender,
        bytes32 acceptedCommitment,
        bytes32 conflictingCommitment,
        bytes32 conflictingPayloadDigest,
        bytes32 conflictingStateDigest,
        uint256 timestamp
    );

    event ReceiverObservationSubmitted(
        bytes32 indexed sessionId,
        uint256 indexed iteration,
        uint256 indexed senderUavId,
        uint256 receiverUavId,
        bytes32 observedCommitment,
        bool matchesFinalizedCommitment,
        uint256 timestamp
    );

    event InconsistentPacketObserved(
        bytes32 indexed sessionId,
        uint256 indexed iteration,
        uint256 indexed senderUavId,
        uint256 receiverUavId,
        bytes32 finalizedCommitment,
        bytes32 observedCommitment,
        uint256 timestamp
    );

    // ---------------------------------------------------------------------
    // Sender-side commitment submission
    // ---------------------------------------------------------------------

    /**
     * @notice Submit the UAV's round commitment.
     * @dev If the sender already finalized a different commitment for the same
     *      (sessionId, iteration), the function records the conflict and returns false.
     *      It does not revert, so the malicious evidence remains visible on-chain.
     *
     * @param sessionId Unique localization/ADMM session identifier.
     * @param iteration ADMM/localization iteration index.
     * @param commitment Round commitment c_i^k.
     * @param payloadDigest Digest of the serialized payload m_i^k.
     * @param stateDigest Digest of the serialized state x_i^k.
     * @param xScaled Optional scaled x-coordinate for readability.
     * @param yScaled Optional scaled y-coordinate for readability.
     * @return accepted True if this is the first valid commitment or an exact duplicate;
     *                  false if it conflicts with a previously accepted commitment.
     */
    function submitStateCommitment(
        bytes32 sessionId,
        uint256 iteration,
        bytes32 commitment,
        bytes32 payloadDigest,
        bytes32 stateDigest,
        int256 xScaled,
        int256 yScaled
    ) external onlyRegisteredUAV returns (bool accepted) {
        require(sessionId != bytes32(0), "Invalid session id");
        require(commitment != bytes32(0), "Invalid commitment");
        require(payloadDigest != bytes32(0), "Invalid payload digest");
        require(stateDigest != bytes32(0), "Invalid state digest");

        uint256 uavId = uavsByAddress[msg.sender].uavId;
        StateRecord storage existing = stateRecords[sessionId][iteration][uavId];

        if (!existing.exists) {
            stateRecords[sessionId][iteration][uavId] = StateRecord({
                exists: true,
                uavId: uavId,
                sender: msg.sender,
                sessionId: sessionId,
                iteration: iteration,
                commitment: commitment,
                payloadDigest: payloadDigest,
                stateDigest: stateDigest,
                xScaled: xScaled,
                yScaled: yScaled,
                timestamp: block.timestamp
            });

            emit StateCommitted(
                sessionId,
                iteration,
                uavId,
                msg.sender,
                commitment,
                payloadDigest,
                stateDigest,
                xScaled,
                yScaled,
                block.timestamp
            );

            return true;
        }

        // Same commitment is harmless and indicates retransmission/duplicate submission.
        if (
            existing.commitment == commitment &&
            existing.payloadDigest == payloadDigest &&
            existing.stateDigest == stateDigest
        ) {
            emit DuplicateConsistentCommitment(
                sessionId,
                iteration,
                uavId,
                commitment,
                block.timestamp
            );
            return true;
        }

        // Different commitment for the same sender-round pair indicates equivocation.
        conflictingCommitments[sessionId][iteration][uavId].push(commitment);

        emit EquivocationDetected(
            sessionId,
            iteration,
            uavId,
            msg.sender,
            existing.commitment,
            commitment,
            payloadDigest,
            stateDigest,
            block.timestamp
        );

        return false;
    }

    // ---------------------------------------------------------------------
    // Receiver-side observation submission
    // ---------------------------------------------------------------------

    /**
     * @notice A receiver reports the commitment it actually received from a sender.
     * @dev If the observed commitment differs from the sender's finalized commitment,
     *      the contract records an inconsistency event.
     */
    function submitReceivedCommitment(
        bytes32 sessionId,
        uint256 iteration,
        uint256 senderUavId,
        bytes32 observedCommitment,
        bytes32 observedPayloadDigest
    ) external onlyRegisteredUAV returns (bool matchesFinalizedCommitment) {
        require(sessionId != bytes32(0), "Invalid session id");
        require(observedCommitment != bytes32(0), "Invalid observed commitment");
        require(addressOfUav[senderUavId] != address(0), "Unknown sender UAV");

        uint256 receiverId = uavsByAddress[msg.sender].uavId;
        require(receiverId != senderUavId, "Sender cannot observe itself");

        StateRecord storage finalizedState = stateRecords[sessionId][iteration][senderUavId];
        require(finalizedState.exists, "Sender state not finalized yet");

        bool isMatch = (finalizedState.commitment == observedCommitment);

        observations[sessionId][iteration][senderUavId][receiverId] = ObservationRecord({
            exists: true,
            receiverId: receiverId,
            receiver: msg.sender,
            observedCommitment: observedCommitment,
            observedPayloadDigest: observedPayloadDigest,
            timestamp: block.timestamp,
            matchesFinalizedCommitment: isMatch
        });

        emit ReceiverObservationSubmitted(
            sessionId,
            iteration,
            senderUavId,
            receiverId,
            observedCommitment,
            isMatch,
            block.timestamp
        );

        if (!isMatch) {
            conflictingCommitments[sessionId][iteration][senderUavId].push(observedCommitment);

            emit InconsistentPacketObserved(
                sessionId,
                iteration,
                senderUavId,
                receiverId,
                finalizedState.commitment,
                observedCommitment,
                block.timestamp
            );
        }

        return isMatch;
    }

    // ---------------------------------------------------------------------
    // Validator round checks
    // ---------------------------------------------------------------------

    /**
     * @notice Validator-side consistency check before using a UAV state in ADMM.
     * @return true only if the state exists and no conflicting commitment has been recorded.
     */
    function isConsistent(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId
    ) public view returns (bool) {
        return stateRecords[sessionId][iteration][uavId].exists &&
            conflictingCommitments[sessionId][iteration][uavId].length == 0;
    }

    /**
     * @notice Verify that a candidate commitment matches the finalized sender-round state.
     */
    function verifyCommitment(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId,
        bytes32 commitment
    ) external view returns (bool) {
        StateRecord storage rec = stateRecords[sessionId][iteration][uavId];
        return rec.exists && rec.commitment == commitment;
    }

    /**
     * @notice Optional PoA validator approval for accepting a sender state in an off-chain ADMM round.
     */
    function validatorCheckState(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId
    ) external view onlyValidator returns (bool acceptedForAdmm) {
        return isConsistent(sessionId, iteration, uavId);
    }

    // ---------------------------------------------------------------------
    // Read functions for auditability
    // ---------------------------------------------------------------------

    function getStateRecord(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId
    ) external view returns (
        bool exists,
        address sender,
        bytes32 commitment,
        bytes32 payloadDigest,
        bytes32 stateDigest,
        int256 xScaled,
        int256 yScaled,
        uint256 timestamp
    ) {
        StateRecord storage rec = stateRecords[sessionId][iteration][uavId];
        return (
            rec.exists,
            rec.sender,
            rec.commitment,
            rec.payloadDigest,
            rec.stateDigest,
            rec.xScaled,
            rec.yScaled,
            rec.timestamp
        );
    }

    function getConflictCount(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId
    ) external view returns (uint256) {
        return conflictingCommitments[sessionId][iteration][uavId].length;
    }

    function getConflictCommitment(
        bytes32 sessionId,
        uint256 iteration,
        uint256 uavId,
        uint256 index
    ) external view returns (bytes32) {
        require(index < conflictingCommitments[sessionId][iteration][uavId].length, "Index out of range");
        return conflictingCommitments[sessionId][iteration][uavId][index];
    }

    function getReceiverObservation(
        bytes32 sessionId,
        uint256 iteration,
        uint256 senderUavId,
        uint256 receiverUavId
    ) external view returns (
        bool exists,
        address receiver,
        bytes32 observedCommitment,
        bytes32 observedPayloadDigest,
        uint256 timestamp,
        bool matchesFinalizedCommitment
    ) {
        ObservationRecord storage obs = observations[sessionId][iteration][senderUavId][receiverUavId];
        return (
            obs.exists,
            obs.receiver,
            obs.observedCommitment,
            obs.observedPayloadDigest,
            obs.timestamp,
            obs.matchesFinalizedCommitment
        );
    }

    /**
     * @notice Utility for off-chain code to compute a commitment in the same style.
     * @dev Solidity encoding must match the off-chain encoding to reproduce the same hash.
     */
    function computeCommitment(
        uint256 uavId,
        bytes32 sessionId,
        uint256 iteration,
        bytes32 payloadDigest,
        bytes32 nonce
    ) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(uavId, sessionId, iteration, payloadDigest, nonce));
    }

    function computeDigest(bytes calldata rawPayload) external pure returns (bytes32) {
        return keccak256(rawPayload);
    }
}

